import {validateMessage} from './transport/ws/validation.js';
import type {AIProvider} from './types/ai.js';
import type {SessionStore} from './types/sessionStore.js';

// Acceptance criteria for re-cinq/HALEngine#144: delivering a user's conversation list over WebSocket.

interface SummaryRow {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}

interface WireFrame {
  type: string;
  code?: string;
  message?: string;
  sessionId?: string;
  resumed?: boolean;
  entryCount?: number;
  timestamp?: number;
  conversations?: SummaryRow[];
  entry?: {role: string; content?: string};
}

const EARLIER = '2026-01-01T00:00:00.000Z';
const engines: Array<HalEngine | HalServer> = [];
const sockets: WebSocket[] = [];

describe('delivering a user conversation list over WebSocket', () => {
  afterEach(async () => {
    setLogger();
    for (const socket of sockets.splice(0)) socket.terminate();
    for (const running of engines.splice(0)) await running.stop();
  });

  it("delivers the connecting user's conversations newest first with ISO dates, ignores a forged userId, pages with before, and lets the client resume a listed id", async () => {
    const store = new InMemorySessionStore();
    await seedConversation(store, 's1', 'u1', 'topic one');
    await seedConversation(store, 's2', 'u1', 'topic two');
    await seedConversation(store, 's3', 'u1', 'topic three');
    await seedConversation(store, 'theirs', 'u2', 'private');
    await pause(5);

    const transport = {port: 0, resume: {enabled: true}, history: {enabled: true}};
    const baseUrl = await startHal(store, transport);
    const client = openSocket(baseUrl);
    const [greeting] = await collectUntil(client, 'connected');
    const currentSessionId = greeting.sessionId ?? '';

    client.send(JSON.stringify({type: 'list_conversations', userId: 'u2'}));
    client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    const allFrames = await collectUntil(client, 'pong');
    const allRows = allFrames[0]?.conversations ?? [];

    client.send(JSON.stringify({type: 'list_conversations', limit: 2}));
    client.send(JSON.stringify({type: 'ping', timestamp: 2}));
    const page1Frames = await collectUntil(client, 'pong');
    const page1 = page1Frames.find(frame => frame.type === 'conversation_list')?.conversations ?? [];

    const cursor = page1[1];
    client.send(
      JSON.stringify({
        type: 'list_conversations',
        limit: 2,
        before: {updatedAt: cursor?.updatedAt, sessionId: cursor?.sessionId},
      })
    );
    client.send(JSON.stringify({type: 'ping', timestamp: 3}));
    const page2Frames = await collectUntil(client, 'pong');
    const page2 = page2Frames.find(frame => frame.type === 'conversation_list')?.conversations ?? [];

    const resumedSocket = openSocket(`${baseUrl}?sessionId=s2`);
    const replay = await collectResumed(resumedSocket);

    expect({
      allTypes: allFrames.map(frame => frame.type),
      allIds: allRows.map(row => row.sessionId),
      isoTimestamps: allRows.every(row => isIsoStamp(row.createdAt) && isIsoStamp(row.updatedAt)),
      currentEntryCount: allRows[0]?.entryCount,
      s2EntryCount: allRows.find(row => row.sessionId === 's2')?.entryCount,
      page1Ids: page1.map(row => row.sessionId),
      page2Ids: page2.map(row => row.sessionId),
      replay,
    }).toEqual({
      allTypes: ['conversation_list', 'pong'],
      allIds: [currentSessionId, 's3', 's2', 's1'],
      isoTimestamps: true,
      currentEntryCount: 0,
      s2EntryCount: 1,
      page1Ids: [currentSessionId, 's3'],
      page2Ids: ['s2', 's1'],
      replay: {sessionId: 's2', resumed: true, entryCount: 1, firstContent: 'topic two'},
    });
  });

  it('rejects malformed list_conversations frames in validation and on the wire without stream_end', async () => {
    const accepted = validateMessage({type: 'list_conversations'});
    const badLimits = [0, 201, 1.5, '10'].map(limit => validateMessage({type: 'list_conversations', limit}));
    const badCursors = [
      'not a date',
      {updatedAt: 'not a date', sessionId: 's1'},
      {updatedAt: EARLIER},
      {sessionId: 's1'},
    ].map(before => validateMessage({type: 'list_conversations', before}));

    const transport = {port: 0, resume: {enabled: true}, history: {enabled: true}};
    const baseUrl = await startHal(new InMemorySessionStore(), transport);
    const client = openSocket(baseUrl);
    await collectUntil(client, 'connected');
    client.send(JSON.stringify({type: 'list_conversations', limit: 0}));
    client.send(JSON.stringify({type: 'ping', timestamp: 9}));
    const wireFrames = await collectUntil(client, 'pong');

    expect({
      accepted,
      limitsRefused: badLimits.every(outcome => !outcome.valid && /limit/i.test(outcome.error)),
      cursorsRefused: badCursors.every(outcome => !outcome.valid && /before/i.test(outcome.error)),
      wireTypes: wireFrames.map(frame => `${frame.type}:${frame.code ?? ''}`),
    }).toEqual({
      accepted: {valid: true, data: {type: 'list_conversations'}},
      limitsRefused: true,
      cursorsRefused: true,
      wireTypes: ['error:INVALID_MESSAGE', 'pong:'],
    });
  });

  it('answers list_conversations while a user_message turn is mid-stream, without waiting for stream_end', async () => {
    const gate = deferred();
    const provider: AIProvider = {
      async *sendMessage() {
        yield {type: 'text', text: 'Hel'};
        await gate.until;
        yield {type: 'text', text: 'lo'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const store = new InMemorySessionStore();
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Concurrency test.'}));
    const serverOptions = {
      app: (() => undefined) as unknown as Express,
      wsAuth: async () => ({id: 'u1'}),
      sessionStore: store,
      orchestrator,
      history: {enabled: true},
      resume: {enabled: true},
    };
    const hal = createServer(serverOptions);
    await hal.start(0);
    engines.push(hal);
    const {port} = hal.server.address() as AddressInfo;
    const client = openSocket(`ws://127.0.0.1:${port}/hal/ws`);
    await collectUntil(client, 'connected');

    client.send(JSON.stringify({type: 'user_message', content: 'hi'}));
    await collectUntil(client, 'entry_delta');

    client.send(JSON.stringify({type: 'list_conversations'}));
    client.send(JSON.stringify({type: 'ping', timestamp: 5}));
    const midStream = await collectUntil(client, 'pong');
    gate.release();
    const afterRelease = await collectUntil(client, 'stream_end');

    expect({
      answeredMidStream: midStream.some(frame => frame.type === 'conversation_list'),
      streamEndedAfter: afterRelease.at(-1)?.type === 'stream_end',
    }).toEqual({answeredMidStream: true, streamEndedAfter: true});
  });

  it('refuses list_conversations with UNSUPPORTED when history is off or the store cannot list, and warns when history is enabled without resume', async () => {
    const warnings: string[] = [];
    setLogger({
      debug: () => undefined,
      info: () => undefined,
      warn: (_category, message) => void warnings.push(message),
      error: () => undefined,
    });

    const plainUrl = await startHal(new InMemorySessionStore(), {port: 0});
    const plainClient = openSocket(plainUrl);
    const [plainConnected] = await collectUntil(plainClient, 'connected');
    plainClient.send(JSON.stringify({type: 'list_conversations'}));
    plainClient.send(JSON.stringify({type: 'ping', timestamp: 2}));
    const plainFrames = await collectUntil(plainClient, 'pong');

    const historyOnly = {port: 0, history: {enabled: true}};
    const fiveMemberUrl = await startHal(fiveMemberStore, historyOnly);
    const fiveMemberCode = await requestListErrorCode(fiveMemberUrl);

    const mongoWithoutFind = new MongoSessionStore({collection: fakeCollection()});
    const mongoUrl = await startHal(mongoWithoutFind, historyOnly);
    const mongoCode = await requestListErrorCode(mongoUrl);

    expect({
      connectedKeys: Object.keys(plainConnected).sort(),
      plainWire: plainFrames.map(frame => `${frame.type}:${frame.code ?? ''}`),
      warnedWithoutResume: warnings.some(line => /resume|history/i.test(line)),
      fiveMemberCode,
      mongoCode,
    }).toEqual({
      connectedKeys: ['examplePrompts', 'message', 'sessionId', 'type'],
      plainWire: ['error:UNSUPPORTED', 'pong:'],
      warnedWithoutResume: true,
      fiveMemberCode: 'UNSUPPORTED',
      mongoCode: 'UNSUPPORTED',
    });
  });

  it('answers SERVER_ERROR without leaking store details when listFor fails, logs with sessionId, and keeps the socket open', async () => {
    const errors: Array<{message: string; fields?: Record<string, unknown>}> = [];
    setLogger({
      debug: () => undefined,
      info: () => undefined,
      warn: () => undefined,
      error: (_category, message, fields) => void errors.push({message, fields}),
    });

    const secretDetail = 'secret db uri mongodb://user:pass@host';
    const failingStore = new MongoSessionStore({
      collection: fakeCollection({
        find: () => ({toArray: () => Promise.reject(new Error(secretDetail))}),
      }),
    });
    const transport = {port: 0, resume: {enabled: true}, history: {enabled: true}};
    const baseUrl = await startHal(failingStore, transport);
    const client = openSocket(baseUrl);
    const [greeting] = await collectUntil(client, 'connected');

    client.send(JSON.stringify({type: 'list_conversations'}));
    client.send(JSON.stringify({type: 'ping', timestamp: 42}));
    const frames = await collectUntil(client, 'pong');
    const [errorFrame, pongFrame] = frames;

    expect({
      code: errorFrame?.code,
      leaked: (errorFrame?.message ?? '').includes(secretDetail),
      pongTimestamp: pongFrame?.timestamp,
      loggedSessionId: errors.some(entry => entry.fields?.sessionId === greeting.sessionId),
    }).toEqual({
      code: 'SERVER_ERROR',
      leaked: false,
      pongTimestamp: 42,
      loggedSessionId: true,
    });
  });
});

async function seedConversation(
  store: InMemorySessionStore,
  sessionId: string,
  userId: string,
  content: string
): Promise<void> {
  await pause(5);
  const session = store.create(sessionId, userId);
  session.entries.push({role: 'user', content, timestamp: EARLIER});
}

async function startHal(store: SessionStore, transport: Record<string, unknown>): Promise<string> {
  const engine = createHalEngine({
    provider: {type: 'mock'},
    prompt: {identity: 'History acceptance test.'},
    auth: {ws: async () => ({id: 'u1'})},
    session: store,
    transport: transport as NonNullable<Parameters<typeof createHalEngine>[0]['transport']>,
  });
  await engine.start();
  engines.push(engine);
  const {port} = engine.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
}

async function requestListErrorCode(url: string): Promise<string | undefined> {
  const client = openSocket(url);
  await collectUntil(client, 'connected');
  client.send(JSON.stringify({type: 'list_conversations'}));
  const [errorFrame] = await collectUntil(client, 'error');
  return errorFrame?.code;
}

function openSocket(url: string): WebSocket {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 'test-token']);
  sockets.push(client);
  return client;
}

function collectUntil(client: WebSocket, targetType: string): Promise<WireFrame[]> {
  const seen: WireFrame[] = [];
  return new Promise<WireFrame[]>((resolve, reject) => {
    const onMessage = (raw: Buffer) => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      seen.push(frame);
      if (frame.type !== targetType) return;
      cleanup();
      resolve(seen);
    };
    const onClose = () => {
      cleanup();
      reject(new Error(`Socket closed before ${targetType}`));
    };
    const cleanup = () => {
      client.off('message', onMessage);
      client.off('close', onClose);
    };
    client.on('message', onMessage);
    client.on('close', onClose);
  });
}

async function collectResumed(client: WebSocket): Promise<{
  sessionId?: string;
  resumed?: boolean;
  entryCount?: number;
  firstContent?: string;
}> {
  const frames: WireFrame[] = [];
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      frames.push(frame);
      if (frame.type === 'connected') client.send(JSON.stringify({type: 'ping', timestamp: 7}));
      if (frame.type === 'pong') resolve();
    });
  });
  const connected = frames.find(frame => frame.type === 'connected');
  const firstUpsert = frames.find(frame => frame.type === 'entry_upsert');
  return {
    sessionId: connected?.sessionId,
    resumed: connected?.resumed,
    entryCount: connected?.entryCount,
    firstContent: firstUpsert?.entry?.content,
  };
}

function isIsoStamp(value: unknown): boolean {
  return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}T/.test(value) && Number.isFinite(Date.parse(value));
}

function pause(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function deferred(): {until: Promise<void>; release: () => void} {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release};
}
